EN = {}  # navn -> engelsk beskrivelse af den færdige ret


def r(navn, beskr, niveau, kat, koekken, tid, ing, trin, en, tidligt=False):
    EN[navn] = en
    return R(navn, beskr, niveau, kat, koekken, tid, ing, trin, tidligt)


